/// Every event Stoic emits: its stable name, its usual level, and what it
/// means.
///
/// Event names are API. Dashboards, log queries and alerts are built on
/// them, so a name is never renamed or removed in a minor release, and the
/// test suite fails if a source file emits a name missing from this catalog
/// or the catalog lists a name nothing emits.
public enum EventCatalog {
    /// One documented event.
    public struct Entry: Sendable, Hashable {
        public let name: EventName
        public let level: Event.Level
        public let meaning: String
    }

    /// Every event, sorted by name.
    public static let entries: [Entry] = [
        Entry(name: "abandoned.completed", level: .notice, meaning: "Abandoned work finally finished; reports how late it was."),
        Entry(name: "abandoned.started", level: .warning, meaning: "Work ignored its deadline or its caller's cancellation and was abandoned, still running."),
        Entry(name: "abandoned.wedged", level: .error, meaning: "A label reached its limit of abandoned work and refused a new call."),
        Entry(name: "breaker.closed", level: .info, meaning: "A circuit breaker closed: its probes succeeded, or it was forced closed."),
        Entry(name: "breaker.defect", level: .error, meaning: "A call through a breaker failed with a defect: a bug, not counted against the dependency."),
        Entry(name: "breaker.half_open", level: .info, meaning: "A circuit breaker's open period ended; it admits probe calls."),
        Entry(name: "breaker.ignored", level: .debug, meaning: "A call's outcome was not counted: cancelled, a defect, a rejection, or stale."),
        Entry(name: "breaker.opened", level: .warning, meaning: "A circuit breaker opened: the failure or slow-call rate crossed its threshold, or a probe failed."),
        Entry(name: "breaker.recorded", level: .debug, meaning: "A call's outcome was counted in a breaker's window."),
        Entry(name: "breaker.rejected", level: .info, meaning: "A circuit breaker refused a call while open or out of probe permits."),
        Entry(name: "breaker.reset", level: .info, meaning: "A circuit breaker was reset or forced into a state."),
        Entry(name: "bulkhead.rejected", level: .info, meaning: "A bulkhead refused a call: every slot and queue place was taken."),
        Entry(name: "cache.refresh_failed", level: .warning, meaning: "A cache's background refresh failed; the stale value was kept."),
        Entry(name: "channel.dropped", level: .debug, meaning: "A channel's overflow policy discarded an element."),
        Entry(name: "deadline.expired", level: .notice, meaning: "A deadline passed before its operation finished; reports the budget, the overrun and how the operation ended."),
        Entry(name: "debounce.dropped", level: .debug, meaning: "A debounced call did not run: a newer call replaced it, or it fell inside a burst that lets none run."),
        Entry(name: "download.cancelled", level: .info, meaning: "A download was cancelled: it is not a failure; reports the bytes held and whether the partial file was kept."),
        Entry(name: "download.cleanup_failed", level: .warning, meaning: "A download could not make its partial file durable, delete it, or remove a leftover while stopping; the error that stopped it is the one reported."),
        Entry(name: "download.durability_unknown", level: .warning, meaning: "A file or directory was placed, or a resume record written, but the directory sync that makes it survive a power loss failed: it is treated as placed. Reports what."),
        Entry(name: "download.failed", level: .warning, meaning: "A download ended in failure; reports the error's kind (its text is private), the bytes held and whether the partial file was kept."),
        Entry(name: "download.file_reused", level: .info, meaning: "A bundle's file was already whole in the staging directory, at its expected size and with a digest that checks, so it was verified and not fetched again."),
        Entry(name: "download.placed", level: .info, meaning: "A verified file, or a bundle's directory, was moved into place; reports the bytes and whether the move is known to be durable."),
        Entry(name: "download.restarted", level: .notice, meaning: "A download started a file over from the first byte, or threw away what an earlier run left; reports why (range ignored, validator changed, record missing, digest mismatch, …) and how many bytes were discarded."),
        Entry(name: "download.resumed", level: .info, meaning: "A download resumes from a partial file an earlier run left; reports the offset and how many bytes past what the record vouched for were cut off."),
        Entry(name: "download.retry", level: .info, meaning: "A download waits to ask again after a failed request or a cut connection; reports the attempt, the wait, why, and the bytes held. Never a URL or its query."),
        Entry(name: "download.started", level: .info, meaning: "A download of one file began; reports the method, host and path of the request, never its query."),
        Entry(name: "download.verification_failed", level: .warning, meaning: "A complete file's digest was not the expected one; reports the algorithm, the attempt and both digests."),
        Entry(name: "download.verified", level: .info, meaning: "A complete file's digest, computed while it streamed, is the expected one."),
        Entry(name: "hedge.all_failed", level: .notice, meaning: "Every attempt of a hedged call failed; the first failure was thrown."),
        Entry(name: "hedge.attempt_failed", level: .debug, meaning: "One attempt of a hedged call failed."),
        Entry(name: "hedge.budget_exhausted", level: .notice, meaning: "A hedge was not started because the retry budget had no token."),
        Entry(name: "hedge.deadline_skip", level: .notice, meaning: "A hedge was not started because it could not finish before the deadline."),
        Entry(name: "hedge.started", level: .debug, meaning: "A hedged call started another attempt alongside the slow one."),
        Entry(name: "hedge.won", level: .debug, meaning: "An attempt of a hedged call succeeded first."),
        Entry(name: "http.coalesced", level: .debug, meaning: "An identical GET was already in flight; this caller shares its response instead of making another request."),
        Entry(name: "http.decoded_with_warnings", level: .warning, meaning: "A response body decoded, but the schema decided something on the way: a key it did not declare, a field repaired to its default, an element dropped. Reports the request's method, host and path, the counts of warnings and repairs and their issue codes; the paths are private. Never a value or the body."),
        Entry(name: "http.decoding_failed", level: .notice, meaning: "A response body did not match its schema. Reports the request's method, host and path, the number of errors and the body's size in bytes, never the body."),
        Entry(name: "http.failed", level: .warning, meaning: "A request ended in failure after its attempts; reports the error kind and the attempts made."),
        Entry(name: "http.reauthenticate_failed", level: .warning, meaning: "The reauthenticate hook failed after a 401; the request is not replayed. Reports the failure kind, never the credentials."),
        Entry(name: "http.reauthenticated", level: .info, meaning: "The reauthenticate hook succeeded after a 401 and the request is being replayed once."),
        Entry(name: "http.redirected", level: .info, meaning: "The client is following a redirect; reports the status, the hop number, the method, host and path it goes to, and whether the origin changed (which leaves credentials behind). Never a header or a query string."),
        Entry(name: "http.request", level: .debug, meaning: "One attempt reached the transport; reports method, host, path, status or outcome, duration and attempt number."),
        Entry(name: "http.response_too_large", level: .warning, meaning: "A response body passed the byte limit and the transfer was cancelled."),
        Entry(name: "http.retry", level: .info, meaning: "A request is being retried; reports the attempt number, the wait since the last attempt and why that one failed."),
        Entry(name: "launch.interrupted", level: .info, meaning: "A launch that never became stable was not counted as a crash: the app was backgrounded, the device restarted, or the build changed."),
        Entry(name: "launch.record_failed", level: .error, meaning: "A launch could not be recorded in the launch guard's state file (a full or read-only disk): the launch goes on, judged on the history that could be read, and the next launch will not count this one."),
        Entry(name: "launch.safe_mode", level: .error, meaning: "Too many launches in a row did not finish; the app was told to start in safe mode."),
        Entry(name: "launch.stable", level: .info, meaning: "A launch was marked stable: the unclean-launch count starts over."),
        Entry(name: "launch.unclean_detected", level: .warning, meaning: "The previous launch never became stable and never exited cleanly."),
        Entry(name: "lifecycle.terminate_completed", level: .info, meaning: "A Mac app's shutdown finished before its deadline; the app quits."),
        Entry(name: "lifecycle.terminate_overran", level: .error, meaning: "A Mac app's shutdown overran its deadline; the app quits anyway."),
        Entry(name: "lifecycle.terminate_started", level: .info, meaning: "A Mac app began its graceful shutdown."),
        Entry(name: "map.failed", level: .notice, meaning: "A concurrent map stopped at its first failure; that failure was thrown and the others seen while the rest wound down are in the event."),
        Entry(name: "operation.backend_conflict", level: .error, meaning: "Two backends were declared with one name and a different kind or capacity: a bug. The first declaration in the process wins."),
        Entry(name: "operation.key_ambiguous", level: .error, meaning: "A keyed operation without a key was performed in a child task of an enclosing attempt, where its occurrence (and so its derived key) is not reproducible: a bug. It is not repeated; pass idempotencyKey: from the data."),
        Entry(name: "operation.key_unread", level: .error, meaning: "A keyed operation whose key Stoic made never read attempt.idempotencyKey, so it sent no key: a bug. It is not repeated."),
        Entry(name: "operation.nested_admission", level: .debug, meaning: "A perform inside an attempt of a perform on the same backend found the enclosing slot borrowed by another nested call, and took a slot of its own."),
        Entry(name: "operation.outcome_unknown", level: .warning, meaning: "A keyed or non-repeatable operation gave up after an attempt reached the backend and was cut off or failed transiently: it may have acted. Never reported as cancellation; reconcile under its key."),
        Entry(name: "operation.registry_full", level: .warning, meaning: "The backend registry passed its limit with every backend's work in flight, so it grew rather than forget one; reported once per registry."),
        Entry(name: "operation.urgency_capped", level: .debug, meaning: "An operation ran at its declared ceiling, below the caller's urgency."),
        Entry(name: "race.all_failed", level: .notice, meaning: "Every operation in a race failed; the first failure was thrown and the others are in the event."),
        Entry(name: "race.won", level: .debug, meaning: "An operation won a race; reports which and how long it took."),
        Entry(name: "ratelimiter.oversized", level: .error, meaning: "A request asked for more permits than the limiter's burst can ever hold."),
        Entry(name: "ratelimiter.rejected", level: .info, meaning: "A rate limiter refused a request: its queue was full or the wait would outlive the deadline."),
        Entry(name: "ratelimiter.waited", level: .debug, meaning: "A request waited for rate-limiter permits."),
        Entry(name: "recur.ended", level: .debug, meaning: "A recurring loop ended: stopped, schedule ended, or cancelled."),
        Entry(name: "retry.after_capped", level: .notice, meaning: "A retryAfter request exceeded five minutes and was capped."),
        Entry(name: "retry.attempt_failed", level: .info, meaning: "An attempt failed and another will follow after the reported delay."),
        Entry(name: "retry.breaker_open", level: .notice, meaning: "A retry stopped because a circuit breaker is open for longer than the schedule would wait."),
        Entry(name: "retry.budget_exhausted", level: .warning, meaning: "A retry was refused because its budget had no token left."),
        Entry(name: "retry.cancelled", level: .debug, meaning: "A retry stopped because the task running it was cancelled."),
        Entry(name: "retry.deadline_skip", level: .notice, meaning: "A retry was skipped because it could not finish before the deadline."),
        Entry(name: "retry.defect", level: .error, meaning: "A retry stopped because the failure is a defect: a bug, not a fault."),
        Entry(name: "retry.exhausted", level: .notice, meaning: "A retry's schedule allowed no further attempt."),
        Entry(name: "retry.nested", level: .notice, meaning: "A retry inside another retry's attempt made a single attempt."),
        Entry(name: "retry.permanent", level: .info, meaning: "A retry stopped because the failure was classified as permanent."),
        Entry(name: "retry.stopped", level: .info, meaning: "A retry stopped without repeating an attempt that a declared operation inside it had settled (reason inner_settled)."),
        Entry(name: "retry.succeeded", level: .info, meaning: "An operation succeeded after at least one retry."),
        Entry(name: "saga.compensation_failed", level: .error, meaning: "A saga's compensation threw; the remaining compensations still ran and the saga's error is unchanged."),
        Entry(name: "saga.compensation_overlapped", level: .warning, meaning: "A saga's compensation started while an earlier one, abandoned for overrunning, was still running: the two ran out of order."),
        Entry(name: "scope.child_failed", level: .error, meaning: "A task scope's fork failed; the body and the other forks were cancelled."),
        Entry(name: "scope.finalizer_abandoned", level: .error, meaning: "A finalizer overran its allowance and was abandoned."),
        Entry(name: "scope.finalizer_failed", level: .error, meaning: "A finalizer threw; the scope's outcome was unchanged."),
        Entry(name: "scope.finalizer_slow", level: .notice, meaning: "A finalizer used more than half its allowance."),
        Entry(name: "scope.fork_abandoned", level: .error, meaning: "A fork ignored cancellation past the scope's fork timeout and was abandoned."),
        Entry(name: "scope.fork_after_exit", level: .error, meaning: "Work tried to fork into a task scope that had already ended."),
        Entry(name: "scope.release_quarantined", level: .warning, meaning: "A release was skipped because work abandoned in its scope may still be using the resource; it was leaked on purpose."),
        Entry(name: "sealed.file_adopted", level: .notice, meaning: "A plaintext file was sealed in place and every plaintext copy the store kept beside it was removed. Reports the purpose, the plaintext's size and how many leftovers went; never the contents or the context's ids."),
        Entry(name: "sealed.journal_compacted", level: .info, meaning: "A sealed journal's records were folded into a snapshot sealed under the current key. Reports the purpose, how many records, whether the key was rotated, how many old keys were retired (the crypto-shredding) and how many unreadable values were discarded."),
        Entry(name: "sealed.key_rotated", level: .notice, meaning: "A keyring made a new current key and stored the ring before using it. Reports the keyring's name and how many keys it holds; never a key or an identifier."),
        Entry(name: "sealed.keyring_created", level: .notice, meaning: "The custody held no keyring and one was created: nothing sealed before can be opened. Reports the keyring's name."),
        Entry(name: "sealed.keyring_destroyed", level: .notice, meaning: "A keyring was deleted from its custody: everything sealed under its keys is lost for ever. Reports the keyring's name."),
        Entry(name: "sealed.keys_retired", level: .notice, meaning: "Keys were retired from a keyring: what was sealed under them can no longer be opened. Reports the keyring's name and how many keys went."),
        Entry(name: "sealed.open_failed", level: .warning, meaning: "A sealed file did not open. Reports the purpose of its context, the kind (tampered, torn, unknown_key, not_sealed, unsupported_format) and whether it was the current file or the previous generation; never the data, a key or an identifier."),
        Entry(name: "sealed.records_unreadable", level: .error, meaning: "A replay of a sealed journal found records, or the snapshot, that could not be opened. Reports the purpose and the counts by kind (tampered, unknown key, not sealed, other); the records that did open are returned all the same."),
        Entry(name: "sealed.shred_incomplete", level: .error, meaning: "A compaction that rotates the key finished, but the old keys could not be retired, so what was sealed before is still readable by anyone who can open the keyring. Reports the purpose and how many keys remain to retire."),
        Entry(name: "semaphore.reentrant", level: .error, meaning: "A task asked for a permit of a semaphore it already holds: a possible self-deadlock."),
        Entry(name: "semaphore.rejected", level: .info, meaning: "A semaphore waiter left without a permit: cancelled or past its deadline."),
        Entry(name: "service.start_abandoned", level: .error, meaning: "A service's start ignored its timeout or the graph's cancellation past the grace; it was abandoned, and is stopped at once if it finishes starting after all."),
        Entry(name: "service.start_failed", level: .error, meaning: "A service failed to start or timed out; the graph stops what already started and throws startFailed."),
        Entry(name: "service.started", level: .debug, meaning: "A service in a service graph finished starting."),
        Entry(name: "service.stopped", level: .info, meaning: "A service stopped; reports how long the stop took and whether it failed (warning, with the error)."),
        Entry(name: "settings.busy", level: .warning, meaning: "A hand-edited settings update could not take the lock on the file because another process held it (for the whole wait, or from update, at the moment it asked); nothing was read or written. Reports how long it waited, in milliseconds."),
        Entry(name: "settings.change_dropped", level: .warning, meaning: "A reader of a settings store's changes had fallen further behind than its buffer, and the oldest changes it had not read were dropped; reports how many. A history built from the stream has a gap."),
        Entry(name: "settings.loaded", level: .debug, meaning: "Settings were loaded; reports where from and how many issues the load found."),
        Entry(name: "settings.lock_release_failed", level: .warning, meaning: "Letting go of the lock after a hand-edited settings update failed; the update's outcome is unchanged, and the lock is dropped with its descriptor."),
        Entry(name: "settings.materialized", level: .info, meaning: "The settings file did not exist and was written (sparse, with the file header), on the app's asking."),
        Entry(name: "settings.migrated", level: .info, meaning: "Settings in an older format were migrated as they were read."),
        Entry(name: "settings.newer_format", level: .warning, meaning: "Settings were written by a newer app version; opened read-only and left untouched."),
        Entry(name: "settings.recovered", level: .warning, meaning: "The settings file was unusable; the previous generation was used and the file quarantined."),
        Entry(name: "settings.rejected", level: .notice, meaning: "A settings update produced a value the schema refuses; nothing changed."),
        Entry(name: "settings.reload_failed", level: .warning, meaning: "A reload the file watcher started failed (an app-owned file whose read failed); the value is as it was."),
        Entry(name: "settings.reloaded", level: .info, meaning: "A reload found a hand-edited settings file changed (by a person or another process) and published what it holds."),
        Entry(name: "settings.repaired", level: .warning, meaning: "Invalid settings fields fell back to their defaults; reports how many."),
        Entry(name: "settings.repeated_keys", level: .warning, meaning: "A hand-edited settings file says a key more than once; the last is used, and the file is left as it is until the next update, which writes only that one. Reports how many repeats and which occurrence is used. Each is a repeated_key issue with both places."),
        Entry(name: "settings.replaced", level: .warning, meaning: "A hand-edited settings file that could not be read was replaced, on the app's asking, after the person's bytes were copied and the copy checked. Reports where the copy is."),
        Entry(name: "settings.reset", level: .error, meaning: "No settings file was usable; the defaults were used and the files quarantined."),
        Entry(name: "settings.save_failed", level: .error, meaning: "Settings could not be written, and the value and the file are as they were; or they were written but could not be made durable, and the new value is published (the error says which)."),
        Entry(name: "settings.saved", level: .debug, meaning: "A settings update was written durably and published."),
        Entry(name: "settings.unparsed", level: .warning, meaning: "A hand-edited settings file cannot be used (not JSON, not UTF-8, the wrong shape, or unreadable). It is left exactly as it is; the last good value (or the defaults) stands. Reports the reason, the line and column of the first problem, and which value is kept."),
        Entry(name: "settings.update_refused", level: .warning, meaning: "A hand-edited settings update was refused because the file, as it stands, cannot be used; nothing was written over it."),
        Entry(name: "singleflight.abandoned", level: .info, meaning: "Every caller left a flight, so its operation was cancelled."),
        Entry(name: "singleflight.joined", level: .debug, meaning: "A caller joined a flight already in progress."),
        Entry(name: "slot.superseded", level: .debug, meaning: "A task slot's work was superseded by newer work."),
        Entry(name: "slot.superseded_late", level: .info, meaning: "Superseded work finished anyway; its result was dropped."),
        Entry(name: "span.ended", level: .debug, meaning: "A span ended; reports its duration on the ambient clock and its status (ok, error, cancelled)."),
        Entry(name: "span.started", level: .debug, meaning: "A span began; reports its id, its trace, its parent and its attributes."),
        Entry(name: "statemachine.duplicate_work", level: .error, meaning: "State work was registered again under a label it already has, for the same state; the registration was ignored."),
        Entry(name: "statemachine.invalid", level: .error, meaning: "An event arrived in a state that declares it invalid."),
        Entry(name: "statemachine.stale_event", level: .info, meaning: "An event from an earlier visit to a state was dropped."),
        Entry(name: "statemachine.transition", level: .debug, meaning: "A state machine changed state."),
        Entry(name: "statemachine.work_abandoned", level: .error, meaning: "State work did not stop within its shutdown timeout after its visit ended; it was abandoned so the next visit's work could start."),
        Entry(name: "store.corrupt_quarantined", level: .warning, meaning: "A stored file failed its checksum or validation and was renamed aside; reports where it went."),
        Entry(name: "store.fullsync_unavailable", level: .notice, meaning: "F_FULLFSYNC is unsupported on this volume; durability fell back to fsync."),
        Entry(name: "store.journal_compacted", level: .info, meaning: "A journal's records were folded into a snapshot and the log truncated."),
        Entry(name: "store.journal_corruption", level: .error, meaning: "A journal had damage in the middle of its log with intact records after it; the damaged stretch was skipped and the records after it kept. Reports its offset, length and how many records were lost."),
        Entry(name: "store.journal_removed", level: .notice, meaning: "A journal and the files it keeps beside it (snapshot, tombstone, lock, damaged-log copies) were removed; reports the path and how many files went."),
        Entry(name: "store.journal_snapshot_lost", level: .error, meaning: "A journal's snapshot was lost (corrupt, and quarantined), and the records it folded in with it; open refuses until the app accepts the loss. Reports whether this open accepted it."),
        Entry(name: "store.journal_truncated", level: .warning, meaning: "A journal's torn or corrupt tail was cut at open; reports how many bytes were dropped."),
        Entry(name: "store.outbox_delivered", level: .debug, meaning: "An outbox entry was delivered and its acknowledgement made durable."),
        Entry(name: "store.outbox_delivery_failed", level: .warning, meaning: "An outbox entry used up its attempts or failed permanently; it stays pending."),
        Entry(name: "store.outbox_discarded", level: .warning, meaning: "An outbox entry was dropped without being delivered, and its removal made durable: the delivery refused it for good, it no longer decodes, or it expired. Reports the kind and the reason; never the entry."),
        Entry(name: "store.outbox_kept", level: .debug, meaning: "An outbox delivery returned keep: the entry stays pending and is not tried again in this run."),
        Entry(name: "store.outbox_maintenance_failed", level: .warning, meaning: "An outbox could not compact its log; nothing was lost."),
